INSERT INTO speed_reading.program_templates(id,"Name","Description","TargetAgeGroupConfigurationId","MinAssessmentScore","MaxAssessmentScore","WeeklyPatternJson","InitialDifficultyLevel","WeeksPerDifficultyIncrease","MaxDifficultyLevel","TotalWeeks","TotalDays","IsActive","DisplayOrder","ProgramType","ExamType","IsAssessment",created_at,created_by,version,"IsDeleted")
SELECT (item->>'id')::uuid,item->>'name',item->>'description',(item->>'age')::uuid,0,100,item->'plan',(item->>'start')::int,2,(item->>'max')::int,4,28,true,(item->>'start')::int,0,null,false,now(),'system:adult-programs-v1',1,false FROM desired_adult_programs ON CONFLICT(id) DO NOTHING;
DO $$ BEGIN
IF (SELECT count(*) FROM speed_reading.program_templates p JOIN desired_adult_programs d ON p.id=(item->>'id')::uuid WHERE p."WeeklyPatternJson"=item->'plan' AND p."IsActive" AND NOT p."IsDeleted")<>5 THEN RAISE EXCEPTION 'Program verification failed'; END IF;
IF EXISTS (SELECT 1 FROM desired_adult_programs d CROSS JOIN LATERAL jsonb_each(item->'plan') w CROSS JOIN LATERAL jsonb_each(CASE WHEN jsonb_typeof(w.value)='object' THEN w.value ELSE '{}'::jsonb END) day CROSS JOIN LATERAL jsonb_array_elements(day.value) task WHERE NOT EXISTS (SELECT 1 FROM speed_reading.exercises e WHERE e.target_age_group_id=(d.item->>'age')::uuid AND e.type_code=task->>'type' AND e.difficulty_level=(task->>'difficulty')::int AND e.is_active AND NOT e.is_deleted)) THEN RAISE EXCEPTION 'Missing exercise at exact program level'; END IF;
END $$;
SELECT "Name","InitialDifficultyLevel","MaxDifficultyLevel","TotalDays" FROM speed_reading.program_templates WHERE id IN (SELECT (item->>'id')::uuid FROM desired_adult_programs) ORDER BY "InitialDifficultyLevel";
COMMIT;
